  ('16e5d67c-b70a-547a-864c-405075f47dfa', null, (select id from public.skills where slug = 'write-g5-opinion-writing'), null, 'hard',
   $q$Which sentence would make the best concluding statement for the draft?$q$, $q$[{"text":"Every town in the world must turn off all of its lights.","is_correct":false,"misconception_token":"overstated-claim"},{"text":"Turning down the lights would bring back the stars and protect wildlife, so our town should do it.","is_correct":true},{"text":"Sea turtles hatch from eggs that are buried in the sand.","is_correct":false,"misconception_token":"off-topic-ending"},{"text":"Some parking lots may feel a little darker than before.","is_correct":false,"misconception_token":"ends-with-opposing-idea"}]$q$::jsonb, $q$Turning down the lights would bring back the stars and protect wildlife, so our town should do it.$q$, $q$The correct choice restates the opinion and sums up the two main reasons, stars and wildlife. Saying every town must turn off all its lights goes far beyond the writer's actual opinion in sentence (2).$q$, 'draft', '061b9956-5948-519f-b6d4-00097d602450')
